import type { AccordionHeaderProps } from "../accordion.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { useAccordionSection } from "../hooks/use-accordion-section";
import { AccordionClasses } from "../accordion.styles";

export const AccordionHeader = forwardRef<HTMLButtonElement, AccordionHeaderProps>(
  ({ children, className, headingLevel = 3, ...props }, ref) => {
    const { isExpanded, handleToggle, sectionId, buttonId } = useAccordionSection();

    const HeadingTag = (props.as || `h${headingLevel}`) as keyof JSX.IntrinsicElements;

    return (
      <HeadingTag className={AccordionClasses.header}>
        <button
          ref={ref}
          aria-controls={sectionId}
          aria-expanded={isExpanded}
          className={clsx(AccordionClasses.button, className)}
          data-expanded={isExpanded}
          id={buttonId}
          onClick={handleToggle}
          {...props}
        >
          {children}
        </button>
      </HeadingTag>
    );
  },
);

AccordionHeader.displayName = "Accordion.Header";
